window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-04eac2530ea7e9fd"]={"versions": [{"id": "FIG-04eac2530ea7e9fd", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Funktionales Schichten- und Datenfluss-Diagramm (Use-Case-spezifische Instanziierung des AUTOSAR VMC-Architektur-Referenzmodells).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Signal- und Interaktionspfads für ein isoliertes LKA-System (<em>Lane Keeping Assist</em>) über standardisierte Schnittstellen gemäß <code>AUTOSAR_EXP_AIADASAndVMC</code> (Kapitel 4.3.3).\n</li><li><strong>Systemische Einordnung:</strong> Zeigt die vertikale Dekomposition zwischen logischer Pfadplanung (ADAS-Domäne), Koordinationsschicht (ADAS Manager / Vehicle Manager) und physikalischer Aktorik/Sensorik für die Querführung. Längsführungsaktoren (Bremse, Antrieb) sind in diesem Use Case explizit inaktiv.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten und Software-Komponenten (SWCs)</h5>\n<ul class=\"fig-list\"><li><strong>[3.1.1] ADAS Application (Aktiv):</strong> \n<ul class=\"fig-list\"><li>Funktion: <code>LKA</code> (aktiviert). Berechnet Spurhalte-Trajektorien bzw. Ziel-Krümmungen auf Basis von Umfeldsensordaten.\n</li></ul>\n</li><li><strong>[3.1.2] ADAS-MGR / AMG (Aktiv):</strong>\n<ul class=\"fig-list\"><li>ADAS Manager; aggregiert, koordiniert und arbitriert Funktionsanforderungen mehrerer ADAS-Applikationen vor der Übergabe an das Fahrzeugbewegungsmanagement.\n</li></ul>\n</li><li><strong>[3.1.3] Vehicle-MGR / VMG (Aktiv):</strong>\n<ul class=\"fig-list\"><li>Vehicle Motion Manager; transformiert übergeordnete Bewegungsvorgaben (z. B. Soll-Gierrate, Soll-Kurvenradius) in physikalische Aktor-Stellgrößen der Querdynamik.\n</li></ul>\n</li><li><strong>[3.1.4] Actuator &amp; Sensors (Gemischter Modus):</strong>\n<ul class=\"fig-list\"><li><code>Steering</code> (Aktiv): Lenkaktorik-SWC / Sensor-Aktuator-SWC für die Querführung.\n</li><li><code>Sensors</code> (Aktiv): Fahrzeugzustandssensorik (u. a. Raddrehzahlen, Gierrate, Querbeschleunigung).\n</li><li><code>Powertrain</code> (Inaktiv/Grau): Längsführungsaktor Antrieb; wird von reinem LKA nicht angesteuert.\n</li><li><code>Brake</code> (Inaktiv/Grau): Längsführungsaktor Bremse; für LKA-Regelung ungenutzt.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen (Ports / Interfaces)</h5>\n<ul class=\"fig-list\"><li><strong>Aktive Schnittstellen (Used I/F – Rot hervorgehoben):</strong>\n<ul class=\"fig-list\"><li><code>PLN1</code> (<em>Downlink</em>): Anforderungsschnittstelle von <code>LKA</code> an <code>AMG</code> (Soll-Trajektorie / Soll-Krümmung / Querbeschleunigungsanforderung).\n</li><li><code>PLN2</code> (<em>Uplink</em>): Rückmelde-/Statusschnittstelle von <code>AMG</code> an <code>LKA</code> (Systemverfügbarkeit, Arbitrierungsstatus, Zustandsrückmeldung).\n</li><li><code>VMC1</code> (<em>Downlink</em>): Koordinierte Fahrzeugbewegungsanforderung von <code>AMG</code> an <code>VMG</code> (Vehicle Motion Control Command: Soll-Bewegungsvektor Quer).\n</li><li><code>VMC2</code> (<em>Uplink</em>): Dynamische Bewegungsgrenzen und Ist-Zustände von <code>VMG</code> an <code>AMG</code> (Motion Capabilities, Reglergrenzen).\n</li><li><code>STR1</code> (<em>Downlink</em>): Lenkbefehlsschnittstelle von <code>VMG</code> an <code>Steering</code> (z. B. Soll-Lenkradwinkel, zusätzliches Lenkmoment).\n</li><li><code>STR2</code> (<em>Uplink</em>): Lenkungsrückmeldung von <code>Steering</code> an <code>VMG</code> (Ist-Lenkwinkel, Hand-On-Detection, Aktor-Verfügbarkeit/Übersteuerung).\n</li><li><code>VSS2</code> (<em>Uplink</em>): Messdaten-Schnittstelle von <code>Sensors</code> an <code>VMG</code> (Vehicle Speed / Vehicle State: Fahrzeuggeschwindigkeit, Ist-Gierrate, Querbeschleunigung).\n</li></ul>\n</li><li><strong>Inaktive Schnittstellen (Not used I/F – Grau dargestellt):</strong>\n<ul class=\"fig-list\"><li><code>ACL1</code> / <code>ACL2</code>: Längsbeschleunigungsanforderung und Rückmeldung (Powertrain).\n</li><li><code>BRK1</code> / <code>BRK2</code>: Verzögerungsanforderung und Rückmeldung (Bremssystem).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung (Sensor-Ebene):</strong>\n<ul class=\"fig-list\"><li><code>Sensors</code> liefert kontinuierlich fahrdynamische Basisdaten (Fahrzeuggeschwindigkeit, Gierrate) über <code>VSS2</code> an den <code>VMG</code>.\n</li><li><code>Steering</code> überträgt aktuelle Aktorzustände (Lenkwinkel, Moment) über <code>STR2</code> an den <code>VMG</code>.\n</li></ul>\n</li><li><strong>Fähigkeits- und Zustandsrückmeldung (Bottom-Up):</strong>\n<ul class=\"fig-list\"><li><code>VMG</code> berechnet dynamische Aktor-Limits und übermittelt diese via <code>VMC2</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> spiegelt Systembereitschaft und Randbedingungen via <code>PLN2</code> an die <code>LKA</code>-Applikation.\n</li></ul>\n</li><li><strong>Trajektorien- &amp; Bewegungsplanung (Top-Down):</strong>\n<ul class=\"fig-list\"><li>Bei Spurende/Korrekturbedarf generiert <code>LKA</code> eine laterale Korrekturanforderung via <code>PLN1</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> bewertet/arbitriert die Anforderung und sendet den Stellbefehl über <code>VMC1</code> an den <code>VMG</code>.\n</li></ul>\n</li><li><strong>Aktuatorische Umsetzung:</strong>\n<ul class=\"fig-list\"><li><code>VMG</code> rechnet die laterale Zielgröße in ein Lenkkommando um und steuert via <code>STR1</code> direkt den <code>Steering</code>-Aktor an.\n</li><li>Regelkreis schließt sich zyklisch über die Sensorrückmeldungen (<code>STR2</code>, <code>VSS2</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Konfiguration &amp; VFB:</strong>\n<ul class=\"fig-list\"><li>Sender-Receiver-Interfaces für <code>PLN1/2</code>, <code>VMC1/2</code>, <code>STR1/2</code> und <code>VSS2</code> müssen auf SWC-Ebene im ARXML modelliert werden.\n</li><li>In reinen LKA-ECU-Konfigurationen können die Ports für <code>ACL1/2</code> und <code>BRK1/2</code> unverbunden bleiben (<em>unconnected ports</em>) oder im Kompositionsentwurf weggelassen werden, ohne die VMC-Konformität zu verletzen.\n</li></ul>\n</li><li><strong>Arbitrierungslogik im AMG:</strong>\n<ul class=\"fig-list\"><li>Der Entwickler muss im <code>AMG</code> berücksichtigen, dass bei ausschließlicher LKA-Aktivierung keine Arbitrierung gegen Längsführungsfunktionen (wie ACC) stattfindet, jedoch sichergestellt sein muss, dass bei manuellem Fahrereingriff (Override-Signal aus <code>STR2</code> über <code>VMG</code>-&gt;<code>VMC2</code>) die LKA-Trajektorie verzögerungsfrei degradiert/deaktiviert wird.\n</li></ul>\n</li><li><strong>Echtzeit- und Latenzanforderungen:</strong>\n<ul class=\"fig-list\"><li>Der Pfad <code>PLN1 -&gt; VMC1 -&gt; STR1</code> unterliegt harten Latenzgrenzen der Querdynamikregelung. Task-Mapping im RTE-Scheduler erfordert deterministische Zykluszeiten (typisch 10 ms bis 20 ms) entlang der Kette, synchronisiert mit dem Einlesen von <code>VSS2</code>.\n</li></ul>\n</li><li><strong>Sicherheitsbetrachtung (ISO 26262):</strong>\n<ul class=\"fig-list\"><li>Rückmeldepfade (<code>STR2</code>, <code>VSS2</code>) müssen auf Plausibilität und Fehlerflags geprüft werden, um ungewollte Lenkeingriffe (<em>Unintended Steering Intervention</em>) unmittelbar in den sicheren Zustand zu überführen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2a898d4ad9f6756e", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Funktionales Schichten- und Datenfluss-Diagramm (Use-Case-spezifische Instanziierung des AUTOSAR VMC-Architektur-Referenzmodells).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Signal- und Interaktionspfads für ein isoliertes LKA-System (<em>Lane Keeping Assist</em>) über standardisierte Schnittstellen gemäß <code>AUTOSAR_EXP_AIADASAndVMC</code> (Kapitel 4.3.3).\n</li><li><strong>Systemische Einordnung:</strong> Zeigt die vertikale Dekomposition zwischen logischer Pfadplanung (ADAS-Domäne), Koordinationsschicht (ADAS Manager / Vehicle Manager) und physikalischer Aktorik/Sensorik für die Querführung. Längsführungsaktoren (Bremse, Antrieb) sind in diesem Use Case explizit inaktiv.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten und Software-Komponenten (SWCs)</h5>\n<ul class=\"fig-list\"><li><strong>[4.1.1] ADAS Application (Aktiv):</strong> \n<ul class=\"fig-list\"><li>Funktion: <code>LKA</code> (aktiviert). Berechnet Spurhalte-Trajektorien bzw. Ziel-Krümmungen auf Basis von Umfeldsensordaten.\n</li></ul>\n</li><li><strong>[4.1.2] ADAS-MGR / AMG (Aktiv):</strong>\n<ul class=\"fig-list\"><li>ADAS Manager; aggregiert, koordiniert und arbitriert Funktionsanforderungen mehrerer ADAS-Applikationen vor der Übergabe an das Fahrzeugbewegungsmanagement.\n</li></ul>\n</li><li><strong>[4.1.3] Vehicle-MGR / VMG (Aktiv):</strong>\n<ul class=\"fig-list\"><li>Vehicle Motion Manager; transformiert übergeordnete Bewegungsvorgaben (z. B. Soll-Gierrate, Soll-Kurvenradius) in physikalische Aktor-Stellgrößen der Querdynamik.\n</li></ul>\n</li><li><strong>[4.1.4] Actuator &amp; Sensors (Gemischter Modus):</strong>\n<ul class=\"fig-list\"><li><code>Steering</code> (Aktiv): Lenkaktorik-SWC / Sensor-Aktuator-SWC für die Querführung.\n</li><li><code>Sensors</code> (Aktiv): Fahrzeugzustandssensorik (u. a. Raddrehzahlen, Gierrate, Querbeschleunigung).\n</li><li><code>Powertrain</code> (Inaktiv/Grau): Längsführungsaktor Antrieb; wird von reinem LKA nicht angesteuert.\n</li><li><code>Brake</code> (Inaktiv/Grau): Längsführungsaktor Bremse; für LKA-Regelung ungenutzt.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen (Ports / Interfaces)</h5>\n<ul class=\"fig-list\"><li><strong>Aktive Schnittstellen (Used I/F – Rot hervorgehoben):</strong>\n<ul class=\"fig-list\"><li><code>PLN1</code> (<em>Downlink</em>): Anforderungsschnittstelle von <code>LKA</code> an <code>AMG</code> (Soll-Trajektorie / Soll-Krümmung / Querbeschleunigungsanforderung).\n</li><li><code>PLN2</code> (<em>Uplink</em>): Rückmelde-/Statusschnittstelle von <code>AMG</code> an <code>LKA</code> (Systemverfügbarkeit, Arbitrierungsstatus, Zustandsrückmeldung).\n</li><li><code>VMC1</code> (<em>Downlink</em>): Koordinierte Fahrzeugbewegungsanforderung von <code>AMG</code> an <code>VMG</code> (Vehicle Motion Control Command: Soll-Bewegungsvektor Quer).\n</li><li><code>VMC2</code> (<em>Uplink</em>): Dynamische Bewegungsgrenzen und Ist-Zustände von <code>VMG</code> an <code>AMG</code> (Motion Capabilities, Reglergrenzen).\n</li><li><code>STR1</code> (<em>Downlink</em>): Lenkbefehlsschnittstelle von <code>VMG</code> an <code>Steering</code> (z. B. Soll-Lenkradwinkel, zusätzliches Lenkmoment).\n</li><li><code>STR2</code> (<em>Uplink</em>): Lenkungsrückmeldung von <code>Steering</code> an <code>VMG</code> (Ist-Lenkwinkel, Hand-On-Detection, Aktor-Verfügbarkeit/Übersteuerung).\n</li><li><code>VSS2</code> (<em>Uplink</em>): Messdaten-Schnittstelle von <code>Sensors</code> an <code>VMG</code> (Vehicle Speed / Vehicle State: Fahrzeuggeschwindigkeit, Ist-Gierrate, Querbeschleunigung).\n</li></ul>\n</li><li><strong>Inaktive Schnittstellen (Not used I/F – Grau dargestellt):</strong>\n<ul class=\"fig-list\"><li><code>ACL1</code> / <code>ACL2</code>: Längsbeschleunigungsanforderung und Rückmeldung (Powertrain).\n</li><li><code>BRK1</code> / <code>BRK2</code>: Verzögerungsanforderung und Rückmeldung (Bremssystem).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung (Sensor-Ebene):</strong>\n<ul class=\"fig-list\"><li><code>Sensors</code> liefert kontinuierlich fahrdynamische Basisdaten (Fahrzeuggeschwindigkeit, Gierrate) über <code>VSS2</code> an den <code>VMG</code>.\n</li><li><code>Steering</code> überträgt aktuelle Aktorzustände (Lenkwinkel, Moment) über <code>STR2</code> an den <code>VMG</code>.\n</li></ul>\n</li><li><strong>Fähigkeits- und Zustandsrückmeldung (Bottom-Up):</strong>\n<ul class=\"fig-list\"><li><code>VMG</code> berechnet dynamische Aktor-Limits und übermittelt diese via <code>VMC2</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> spiegelt Systembereitschaft und Randbedingungen via <code>PLN2</code> an die <code>LKA</code>-Applikation.\n</li></ul>\n</li><li><strong>Trajektorien- &amp; Bewegungsplanung (Top-Down):</strong>\n<ul class=\"fig-list\"><li>Bei Spurende/Korrekturbedarf generiert <code>LKA</code> eine laterale Korrekturanforderung via <code>PLN1</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> bewertet/arbitriert die Anforderung und sendet den Stellbefehl über <code>VMC1</code> an den <code>VMG</code>.\n</li></ul>\n</li><li><strong>Aktuatorische Umsetzung:</strong>\n<ul class=\"fig-list\"><li><code>VMG</code> rechnet die laterale Zielgröße in ein Lenkkommando um und steuert via <code>STR1</code> direkt den <code>Steering</code>-Aktor an.\n</li><li>Regelkreis schließt sich zyklisch über die Sensorrückmeldungen (<code>STR2</code>, <code>VSS2</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Konfiguration &amp; VFB:</strong>\n<ul class=\"fig-list\"><li>Sender-Receiver-Interfaces für <code>PLN1/2</code>, <code>VMC1/2</code>, <code>STR1/2</code> und <code>VSS2</code> müssen auf SWC-Ebene im ARXML modelliert werden.\n</li><li>In reinen LKA-ECU-Konfigurationen können die Ports für <code>ACL1/2</code> und <code>BRK1/2</code> unverbunden bleiben (<em>unconnected ports</em>) oder im Kompositionsentwurf weggelassen werden, ohne die VMC-Konformität zu verletzen.\n</li></ul>\n</li><li><strong>Arbitrierungslogik im AMG:</strong>\n<ul class=\"fig-list\"><li>Der Entwickler muss im <code>AMG</code> berücksichtigen, dass bei ausschließlicher LKA-Aktivierung keine Arbitrierung gegen Längsführungsfunktionen (wie ACC) stattfindet, jedoch sichergestellt sein muss, dass bei manuellem Fahrereingriff (Override-Signal aus <code>STR2</code> über <code>VMG</code>-&gt;<code>VMC2</code>) die LKA-Trajektorie verzögerungsfrei degradiert/deaktiviert wird.\n</li></ul>\n</li><li><strong>Echtzeit- und Latenzanforderungen:</strong>\n<ul class=\"fig-list\"><li>Der Pfad <code>PLN1 -&gt; VMC1 -&gt; STR1</code> unterliegt harten Latenzgrenzen der Querdynamikregelung. Task-Mapping im RTE-Scheduler erfordert deterministische Zykluszeiten (typisch 10 ms bis 20 ms) entlang der Kette, synchronisiert mit dem Einlesen von <code>VSS2</code>.\n</li></ul>\n</li><li><strong>Sicherheitsbetrachtung (ISO 26262):</strong>\n<ul class=\"fig-list\"><li>Rückmeldepfade (<code>STR2</code>, <code>VSS2</code>) müssen auf Plausibilität und Fehlerflags geprüft werden, um ungewollte Lenkeingriffe (<em>Unintended Steering Intervention</em>) unmittelbar in den sicheren Zustand zu überführen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3e9df41108b08fd5", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Funktionales Schichten- und Datenfluss-Diagramm (Use-Case-spezifische Instanziierung des AUTOSAR VMC-Architektur-Referenzmodells).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Signal- und Interaktionspfads für ein isoliertes LKA-System (<em>Lane Keeping Assist</em>) über standardisierte Schnittstellen gemäß <code>AUTOSAR_EXP_AIADASAndVMC</code> (Kapitel 4.3.3).\n</li><li><strong>Systemische Einordnung:</strong> Zeigt die vertikale Dekomposition zwischen logischer Pfadplanung (ADAS-Domäne), Koordinationsschicht (ADAS Manager / Vehicle Manager) und physikalischer Aktorik/Sensorik für die Querführung. Längsführungsaktoren (Bremse, Antrieb) sind in diesem Use Case explizit inaktiv.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Schichten und Software-Komponenten (SWCs)</h5>\n<ul class=\"fig-list\"><li><strong>[4.1.1] ADAS Application (Aktiv):</strong> \n<ul class=\"fig-list\"><li>Funktion: <code>LKA</code> (aktiviert). Berechnet Spurhalte-Trajektorien bzw. Ziel-Krümmungen auf Basis von Umfeldsensordaten.\n</li></ul>\n</li><li><strong>[4.1.2] ADAS-MGR / AMG (Aktiv):</strong>\n<ul class=\"fig-list\"><li>ADAS Manager; aggregiert, koordiniert und arbitriert Funktionsanforderungen mehrerer ADAS-Applikationen vor der Übergabe an das Fahrzeugbewegungsmanagement.\n</li></ul>\n</li><li><strong>[4.1.3] Vehicle-MGR / VMG (Aktiv):</strong>\n<ul class=\"fig-list\"><li>Vehicle Motion Manager; transformiert übergeordnete Bewegungsvorgaben (z. B. Soll-Gierrate, Soll-Kurvenradius) in physikalische Aktor-Stellgrößen der Querdynamik.\n</li></ul>\n</li><li><strong>[4.1.4] Actuator &amp; Sensors (Gemischter Modus):</strong>\n<ul class=\"fig-list\"><li><code>Steering</code> (Aktiv): Lenkaktorik-SWC / Sensor-Aktuator-SWC für die Querführung.\n</li><li><code>Sensors</code> (Aktiv): Fahrzeugzustandssensorik (u. a. Raddrehzahlen, Gierrate, Querbeschleunigung).\n</li><li><code>Powertrain</code> (Inaktiv/Grau): Längsführungsaktor Antrieb; wird von reinem LKA nicht angesteuert.\n</li><li><code>Brake</code> (Inaktiv/Grau): Längsführungsaktor Bremse; für LKA-Regelung ungenutzt.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen (Ports / Interfaces)</h5>\n<ul class=\"fig-list\"><li><strong>Aktive Schnittstellen (Used I/F – Rot hervorgehoben):</strong>\n<ul class=\"fig-list\"><li><code>PLN1</code> (<em>Downlink</em>): Anforderungsschnittstelle von <code>LKA</code> an <code>AMG</code> (Soll-Trajektorie / Soll-Krümmung / Querbeschleunigungsanforderung).\n</li><li><code>PLN2</code> (<em>Uplink</em>): Rückmelde-/Statusschnittstelle von <code>AMG</code> an <code>LKA</code> (Systemverfügbarkeit, Arbitrierungsstatus, Zustandsrückmeldung).\n</li><li><code>VMC1</code> (<em>Downlink</em>): Koordinierte Fahrzeugbewegungsanforderung von <code>AMG</code> an <code>VMG</code> (Vehicle Motion Control Command: Soll-Bewegungsvektor Quer).\n</li><li><code>VMC2</code> (<em>Uplink</em>): Dynamische Bewegungsgrenzen und Ist-Zustände von <code>VMG</code> an <code>AMG</code> (Motion Capabilities, Reglergrenzen).\n</li><li><code>STR1</code> (<em>Downlink</em>): Lenkbefehlsschnittstelle von <code>VMG</code> an <code>Steering</code> (z. B. Soll-Lenkradwinkel, zusätzliches Lenkmoment).\n</li><li><code>STR2</code> (<em>Uplink</em>): Lenkungsrückmeldung von <code>Steering</code> an <code>VMG</code> (Ist-Lenkwinkel, Hand-On-Detection, Aktor-Verfügbarkeit/Übersteuerung).\n</li><li><code>VSS2</code> (<em>Uplink</em>): Messdaten-Schnittstelle von <code>Sensors</code> an <code>VMG</code> (Vehicle Speed / Vehicle State: Fahrzeuggeschwindigkeit, Ist-Gierrate, Querbeschleunigung).\n</li></ul>\n</li><li><strong>Inaktive Schnittstellen (Not used I/F – Grau dargestellt):</strong>\n<ul class=\"fig-list\"><li><code>ACL1</code> / <code>ACL2</code>: Längsbeschleunigungsanforderung und Rückmeldung (Powertrain).\n</li><li><code>BRK1</code> / <code>BRK2</code>: Verzögerungsanforderung und Rückmeldung (Bremssystem).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung (Sensor-Ebene):</strong>\n<ul class=\"fig-list\"><li><code>Sensors</code> liefert kontinuierlich fahrdynamische Basisdaten (Fahrzeuggeschwindigkeit, Gierrate) über <code>VSS2</code> an den <code>VMG</code>.\n</li><li><code>Steering</code> überträgt aktuelle Aktorzustände (Lenkwinkel, Moment) über <code>STR2</code> an den <code>VMG</code>.\n</li></ul>\n</li><li><strong>Fähigkeits- und Zustandsrückmeldung (Bottom-Up):</strong>\n<ul class=\"fig-list\"><li><code>VMG</code> berechnet dynamische Aktor-Limits und übermittelt diese via <code>VMC2</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> spiegelt Systembereitschaft und Randbedingungen via <code>PLN2</code> an die <code>LKA</code>-Applikation.\n</li></ul>\n</li><li><strong>Trajektorien- &amp; Bewegungsplanung (Top-Down):</strong>\n<ul class=\"fig-list\"><li>Bei Spurende/Korrekturbedarf generiert <code>LKA</code> eine laterale Korrekturanforderung via <code>PLN1</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> bewertet/arbitriert die Anforderung und sendet den Stellbefehl über <code>VMC1</code> an den <code>VMG</code>.\n</li></ul>\n</li><li><strong>Aktuatorische Umsetzung:</strong>\n<ul class=\"fig-list\"><li><code>VMG</code> rechnet die laterale Zielgröße in ein Lenkkommando um und steuert via <code>STR1</code> direkt den <code>Steering</code>-Aktor an.\n</li><li>Regelkreis schließt sich zyklisch über die Sensorrückmeldungen (<code>STR2</code>, <code>VSS2</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Port-Konfiguration &amp; VFB:</strong>\n<ul class=\"fig-list\"><li>Sender-Receiver-Interfaces für <code>PLN1/2</code>, <code>VMC1/2</code>, <code>STR1/2</code> und <code>VSS2</code> müssen auf SWC-Ebene im ARXML modelliert werden.\n</li><li>In reinen LKA-ECU-Konfigurationen können die Ports für <code>ACL1/2</code> und <code>BRK1/2</code> unverbunden bleiben (<em>unconnected ports</em>) oder im Kompositionsentwurf weggelassen werden, ohne die VMC-Konformität zu verletzen.\n</li></ul>\n</li><li><strong>Arbitrierungslogik im AMG:</strong>\n<ul class=\"fig-list\"><li>Der Entwickler muss im <code>AMG</code> berücksichtigen, dass bei ausschließlicher LKA-Aktivierung keine Arbitrierung gegen Längsführungsfunktionen (wie ACC) stattfindet, jedoch sichergestellt sein muss, dass bei manuellem Fahrereingriff (Override-Signal aus <code>STR2</code> über <code>VMG</code>-&gt;<code>VMC2</code>) die LKA-Trajektorie verzögerungsfrei degradiert/deaktiviert wird.\n</li></ul>\n</li><li><strong>Echtzeit- und Latenzanforderungen:</strong>\n<ul class=\"fig-list\"><li>Der Pfad <code>PLN1 -&gt; VMC1 -&gt; STR1</code> unterliegt harten Latenzgrenzen der Querdynamikregelung. Task-Mapping im RTE-Scheduler erfordert deterministische Zykluszeiten (typisch 10 ms bis 20 ms) entlang der Kette, synchronisiert mit dem Einlesen von <code>VSS2</code>.\n</li></ul>\n</li><li><strong>Sicherheitsbetrachtung (ISO 26262):</strong>\n<ul class=\"fig-list\"><li>Rückmeldepfade (<code>STR2</code>, <code>VSS2</code>) müssen auf Plausibilität und Fehlerflags geprüft werden, um ungewollte Lenkeingriffe (<em>Unintended Steering Intervention</em>) unmittelbar in den sicheren Zustand zu überführen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-04eac2530ea7e9fd", "to": "FIG-2a898d4ad9f6756e", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>[3.1.1] ADAS Application:</strong> Blocknummerierung redaktionell aktualisiert zu <code>[4.1.1] ADAS Application</code> (Anpassung an die geänderte Kapitelnummerierung der Spezifikation).\n</li><li><strong>[3.1.2] ADAS-MGR (AMG):</strong> Blocknummerierung redaktionell aktualisiert zu <code>[4.1.2] ADAS-MGR (AMG)</code>.\n</li><li><strong>[3.1.3] Vehicle-MGR (VMG):</strong> Blocknummerierung redaktionell aktualisiert zu <code>[4.1.3] Vehicle-MGR (VMG)</code>.\n</li><li><strong>[3.1.4] Actuator:</strong> Blocknummerierung redaktionell aktualisiert zu <code>[4.1.4] Actuator</code>.\n</li></ul>"}, {"from": "FIG-2a898d4ad9f6756e", "to": "FIG-3e9df41108b08fd5", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
